INSERT INTO _migration_507_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bghl_grammar_s2_001', 'topic_bece_ghlang_grammar', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'In Twi, the pronoun “me” means what?', 'multiple_choice', NULL, '["A. I / me","B. You","C. He or she","D. We"]', 'A', 'Me is the first-person singular pronoun (I/me). The basic set is me (I), wo (you), ɔno (he/she), yɛn (we), mo (you plural) and wɔn (they), so the other options are different pronouns. Therefore the correct answer is A: I / me.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_grammar_s2_002', 'topic_bece_ghlang_grammar', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'In the sentence “Wɔn reba” (they are coming), what does “wɔn” mean?', 'multiple_choice', NULL, '["A. We","B. They","C. You (plural)","D. He"]', 'B', 'Wɔn is the third-person plural pronoun “they”. “We” is yɛn, “you” plural is mo and “he” is ɔno, so they cannot fit the translation “they are coming”. Therefore the correct answer is B: They.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_grammar_s2_003', 'topic_bece_ghlang_grammar', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What is the basic word order of a simple Twi sentence such as “Kwame di aduane” (Kwame eats food)?', 'multiple_choice', NULL, '["A. Verb – subject – object","B. Object – verb – subject","C. Subject – verb – object","D. Subject – object – verb"]', 'C', 'Twi, like English, uses subject – verb – object order: Kwame (subject) di (verb) aduane (object). Placing the verb or object first would produce an unusual or ungrammatical simple sentence. Therefore the correct answer is C: Subject – verb – object.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_grammar_s2_004', 'topic_bece_ghlang_grammar', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'In “Ama redidi” (Ama is eating), what does the prefix “re-” on the verb show?', 'multiple_choice', NULL, '["A. That the action is completed","B. That the action will happen tomorrow","C. That the action is a command","D. That the action is happening now (progressive)"]', 'D', 'The prefix re- marks the progressive aspect — an action in progress: Ama redidi means “Ama is eating”. A completed action would take the a- prefix (Ama adidi — Ama has eaten), so “completed” is the opposite of what re- shows. Therefore the correct answer is D: That the action is happening now (progressive).', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_grammar_s2_005', 'topic_bece_ghlang_grammar', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Which Twi question word means “who”?', 'multiple_choice', NULL, '["A. Hena","B. Dɛn","C. Hen","D. Sɛn"]', 'A', 'Hena asks “who”. Dɛn means “what”, hen means “where” and sɛn means “how”, so each distractor asks a different kind of question. Therefore the correct answer is A: Hena.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_grammar_s2_006', 'topic_bece_ghlang_grammar', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What is the plural of “ɔbarima” (man) in Twi?', 'multiple_choice', NULL, '["A. Mbarima","B. Mmarima","C. Ɔbarimafo","D. Mmarimafo"]', 'B', 'Many Akan nouns form the plural by changing the singular a/ɔ-class prefix to the m(m)-class prefix: ɔbarima becomes mmarima, just as abɔfra (child) becomes mmɔfra (children). The other forms are not valid plurals. Therefore the correct answer is B: Mmarima.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_grammar_s2_007', 'topic_bece_ghlang_grammar', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'In “Kofi akɔ sukuu” (Kofi has gone to school), the prefix “a-” on the verb “kɔ” indicates what?', 'multiple_choice', NULL, '["A. An action still in progress","B. A future action","C. A completed action (perfective past)","D. A negative action"]', 'C', 'The a- prefix marks a completed (perfective) action: akɔ means “has gone”. An action in progress would use re- (Kofi rekɔ — Kofi is going), and negation uses the n- prefix, so a- cannot show progress or negation. Therefore the correct answer is C: A completed action (perfective past).', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bghl_grammar_s2_008', 'topic_bece_ghlang_grammar', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'The “n” inside “mennim” (I do not know) marks which grammatical feature?', 'multiple_choice', NULL, '["A. The future tense","B. A question","C. The plural","D. Negation"]', 'D', 'Menim means “I know”; inserting the negative prefix n- gives mennim, “I do not know”. Negation in Akan is shown by this n- prefix on the verb, not by a separate word for “not”. Therefore the correct answer is D: Negation.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT INTO _migration_507_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_507_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_507_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_507_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-ghlang-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_507_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_507_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_507_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_507_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_507_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM questions q JOIN subjects s ON s.id = q.subject_id AND s.exam_type_id = q.exam_type_id JOIN _migration_507_expected e ON e.id = q.id) = 8 THEN 1 ELSE 0 END;
